// PulseOS typed API client (ADR-003).
//
// src/generated/schema.ts is MACHINE-OWNED — regenerated by `make api-client`
// (scripts/generate-api-client.sh) from the backend's OpenAPI spec; never hand-edit it.
// This file is the only hand-written part: a thin factory that binds the generated
// types to an openapi-fetch runtime and centralizes bearer-token auth so no app ever
// touches fetch() or builds an Authorization header itself.

import createClient, { type Client, type Middleware } from "openapi-fetch";

import type { components, paths } from "./generated/schema";

export type { components, paths };

export type AuthenticatedUser = components["schemas"]["AuthenticatedUserResponse"];
export type PatientProfile = components["schemas"]["PatientProfileResponse"];
export type PatientRegistration = components["schemas"]["PatientRegistrationRequest"];

export type PulseOSClient = Client<paths>;

/** RFC 7807 problem body (docs/API_GUIDELINES.md §Errors). Error responses are produced
 * by global handlers, so they are not part of the generated schema. */
export interface ProblemDetails {
  type?: string;
  title?: string;
  status?: number;
  detail?: string;
  instance?: string;
}

/** Best-effort read of an RFC 7807 `detail` from an unknown error body. */
export function problemDetail(error: unknown): string | undefined {
  if (typeof error === "object" && error !== null && "detail" in error) {
    const detail = (error as ProblemDetails).detail;
    return typeof detail === "string" ? detail : undefined;
  }
  return undefined;
}

export interface PulseOSClientOptions {
  /** API origin, e.g. http://localhost:8000 */
  baseUrl: string;
  /** Returns the current bearer token, or null when unauthenticated. */
  getAccessToken: () => Promise<string | null>;
  /** Injectable for tests; defaults to global fetch. */
  fetch?: typeof globalThis.fetch;
}

export function createPulseOSClient(options: PulseOSClientOptions): PulseOSClient {
  const client = createClient<paths>({
    baseUrl: options.baseUrl,
    fetch: options.fetch,
  });
  const bearerAuth: Middleware = {
    async onRequest({ request }) {
      const token = await options.getAccessToken();
      if (token !== null) {
        request.headers.set("Authorization", `Bearer ${token}`);
      }
      return request;
    },
  };
  client.use(bearerAuth);
  return client;
}

export * from "./ai";
